			}
			if (ucSecondaryIcdYHCT != null)
			{
				object subIcd = subIcdProcessorYHCT.GetValue(ucSecondaryIcdYHCT);
				if (subIcd != null)
				{
					IcdSubCodeYHCT = ((SecondaryIcdDataADO)subIcd).ICD_SUB_CODE;
					IcdTextYHCT = ((SecondaryIcdDataADO)subIcd).ICD_TEXT;
				}
			}
		}
		catch (Exception ex)
		{
			LogSystem.Warn(ex);
		}
	}

