		{
			if (chkPART_EXAM_EYE_BLIND_COLOR__BT.Checked)
			{
				CheckEdit checkEdit = chkPART_EXAM_EYE_BLIND_COLOR__MMD;
				CheckEdit checkEdit2 = chkPART_EXAM_EYE_BLIND_COLOR__MMXLC;
				bool flag2 = (chkPART_EXAM_EYE_BLIND_COLOR__MMV.Checked = false);
				bool @checked = (checkEdit2.Checked = flag2);
