	private void VoBenhAn()
	{
		try
		{
			if (barManager1 == null)
			{
				barManager1 = new BarManager();
				barManager1.Form = this;
			}
			_BarManager = barManager1;
			if (_BarManager == null)
			{
				return;
			}
			if (_Menu == null)
			{
				_Menu = new PopupMenu(_BarManager);
			}
			_Menu.ItemLinks.Clear();
			if (emrMenuPopupProcessor == null)
			{
				emrMenuPopupProcessor = new MediRecordMenuPopupProcessor();
			}
			EmrInputADO emrInputAdo = new EmrInputADO();
			emrInputAdo.TreatmentId = treatment.ID;
			emrInputAdo.PatientId = treatment.PATIENT_ID;
			if (LstEmrCoverConfig != null && LstEmrCoverConfig.Count > 0)
			{
				if (LstEmrCoverConfig.Count == 1)
				{
					emrInputAdo.EmrCoverTypeId = LstEmrCoverConfig.FirstOrDefault().EMR_COVER_TYPE_ID;
				}
				else
				{
					emrInputAdo.lstEmrCoverTypeId = new List<long>();
					emrInputAdo.lstEmrCoverTypeId = LstEmrCoverConfig.Select((HIS_EMR_COVER_CONFIG o) => o.EMR_COVER_TYPE_ID).ToList();
				}
			}
			else if (LstEmrCoverConfigDepartment != null && LstEmrCoverConfigDepartment.Count > 0)
			{
				if (LstEmrCoverConfigDepartment.Count == 1)
				{
					emrInputAdo.EmrCoverTypeId = LstEmrCoverConfigDepartment.FirstOrDefault().EMR_COVER_TYPE_ID;
				}
				else
				{
					emrInputAdo.lstEmrCoverTypeId = new List<long>();
					emrInputAdo.lstEmrCoverTypeId = LstEmrCoverConfigDepartment.Select((HIS_EMR_COVER_CONFIG o) => o.EMR_COVER_TYPE_ID).ToList();
				}
			}
			LogSystem.Info("emrInputAdo: " + LogUtil.TraceData(LogUtil.GetMemberName(() => emrInputAdo), emrInputAdo));
			emrMenuPopupProcessor.InitMenuButton(_Menu, _BarManager, emrInputAdo);
			_Menu.ShowPopup(Cursor.Position);
		}
		catch (Exception ex)
		{
			LogSystem.Error(ex);
		}
	}

