	private void LoadSubIcd(string icdSubCode)
	{
		try
		{
			if (!string.IsNullOrEmpty(icdSubCode))
			{
				List<HIS_ICD> listData = currentIcds.Where((HIS_ICD o) => o.ICD_CODE.Equals(icdSubCode)).ToList();
				List<HIS_ICD> result = ((listData == null) ? null : ((listData.Count > 1) ? listData.Where((HIS_ICD o) => o.ICD_CODE == icdSubCode).ToList() : listData));
				if (result != null && result.Count > 0)
				{
					if (txtIcdSubCode.Text.Contains(";"))
					{
						string[] arrText = txtIcdSubCode.Text.Split(';');
						string txt = "";
						for (int i = 0; i < arrText.Length - 1; i++)
						{
							txt = txt + arrText[i] + ";";
						}
						txtIcdSubCode.Text = txt + result.First().ICD_CODE + ";";
					}
					else
					{
						txtIcdSubCode.Text = result.First().ICD_CODE + ";";
					}
				}
			}
			List<string> arrIcdCode = txtIcdSubCode.Text.Trim().Split(";".ToCharArray(), StringSplitOptions.RemoveEmptyEntries).ToList();
			string icdCodeList = txtIcdSubCode.Text.Trim();
			string messErr = null;
			if (!checkIcdManager.ProcessCheckIcd(txtIcdCode.Text, txtIcdSubCode.Text, ref messErr, IsCheck: false))
			{
				XtraMessageBox.Show(messErr, "Thông báo", MessageBoxButtons.OK);
				string[] parts = icdCodeList.Split(';');
				parts = parts.Where((string p) => !string.IsNullOrEmpty(p)).ToArray();
				icdCodeList = string.Join(";", parts);
				int lastIndexOfSemicolon = icdCodeList.LastIndexOf(';');
				if (lastIndexOfSemicolon > 0)
				{
					icdCodeList = icdCodeList.Substring(0, lastIndexOfSemicolon);
				}
			}
			txtIcdSubCode.Text = icdCodeList;
		}
		catch (Exception ex)
		{
			LogSystem.Warn(ex);
		}
	}

	private void btnFastTrackingCreate_Click(object sender, EventArgs e)
	{
		try
		{
			if ((HisConfigCFG.RequiredWeightHeight_Option == "1" || HisConfigCFG.RequiredWeightHeight_Option == "3") && !ValidDhstOption())
			{
				return;
			}
			ValiTemperatureOption();
			if (!ValidForButtonOtherClick())
			{
				return;
			}
			_ = requiredControl;
			if (requiredControl == 1 && string.IsNullOrEmpty(txtPathologicalProcess.Text.Trim()))
			{
				MessageBox.Show("Quá trình bệnh lý bạn nhập không hợp lệ", HIS.Desktop.Plugins.ExamServiceReqExecute.Resources.ResourceMessage.ThongBao, MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
			}
			else
			{
				if (!VerifyTreatmentFinish() || !CheckExamServiceFinish())
				{
					return;
				}
				GetUcIcdYHCT();
				LogSystem.Debug("Valid ICD");
				if (!ValidIcd(isSave: true))
				{
					return;
				}
				CommonParam param = new CommonParam();
				WaitingManager.Show();
				HisTrackingSDO sdo = new HisTrackingSDO();
				sdo.WorkingRoomId = moduleData.RoomId;
				sdo.Tracking = new HIS_TRACKING();
				sdo.Tracking.DEPARTMENT_ID = WorkPlace.WorkPlaceSDO.FirstOrDefault((WorkPlaceSDO o) => o.RoomId == moduleData.RoomId).DepartmentId;
				sdo.Tracking.CREATOR = ClientTokenManagerStore.ClientTokenManager.GetLoginName();
				sdo.Tracking.ICD_TEXT = txtIcdText.Text.Trim();
				sdo.Tracking.ICD_SUB_CODE = txtIcdSubCode.Text.Trim();
				sdo.Tracking.ICD_NAME = txtIcdMainText.Text.Trim();
				sdo.Tracking.ICD_CODE = txtIcdCode.Text.Trim();
				sdo.Tracking.TRACKING_TIME = Inventec.Common.DateTime.Convert.SystemDateTimeToTimeNumber(DateTime.Now) ?? 0;
				sdo.Tracking.TREATMENT_ID = treatment.ID;
				sdo.Tracking.CONTENT = txtPathologicalProcess.Text + "\r\n" + txtPathologicalHistory.Text + "\r\n" + txtPathologicalHistoryFamily.Text + "\r\n" + txtKhamToanThan.Text + "\r\n" + txtKhamBoPhan.Text.Trim();
				sdo.Tracking.SUBCLINICAL_PROCESSES = txtSubclinical.Text.Trim();
				sdo.Dhst = new HIS_DHST();
				sdo.Dhst.TREATMENT_ID = treatment.ID;
				sdo.Dhst.EXECUTE_ROOM_ID = moduleData.RoomId;
				sdo.Dhst.EXECUTE_LOGINNAME = ClientTokenManagerStore.ClientTokenManager.GetLoginName();
				sdo.Dhst.EXECUTE_USERNAME = ClientTokenManagerStore.ClientTokenManager.GetUserName();
				if (spinBelly.EditValue != null)
				{
					sdo.Dhst.BELLY = Inventec.Common.Number.Get.RoundCurrency(spinBelly.Value, 2);
				}
				if (spinBloodPressureMax.EditValue != null)
				{
					sdo.Dhst.BLOOD_PRESSURE_MAX = Parse.ToInt64(spinBloodPressureMax.Value.ToString());
				}
				if (spinBloodPressureMin.EditValue != null)
				{
					sdo.Dhst.BLOOD_PRESSURE_MIN = Parse.ToInt64(spinBloodPressureMin.Value.ToString());
				}
				if (spinBreathRate.EditValue != null)
				{
					sdo.Dhst.BREATH_RATE = Inventec.Common.Number.Get.RoundCurrency(spinBreathRate.Value, 2);
				}
				sdo.Dhst.CAPILLARY_BLOOD_GLUCOSE = null;
				if (spinChest.EditValue != null)
				{
					sdo.Dhst.CHEST = Inventec.Common.Number.Get.RoundCurrency(spinChest.Value, 2);
				}
				if (dtExecuteTime.EditValue != null)
				{
					sdo.Dhst.EXECUTE_TIME = Inventec.Common.DateTime.Convert.SystemDateTimeToTimeNumber(dtExecuteTime.DateTime);
				}
				if (spinHeight.EditValue != null)
				{
					sdo.Dhst.HEIGHT = Inventec.Common.Number.Get.RoundCurrency(spinHeight.Value, 2);
				}
				sdo.Dhst.NOTE = null;
				if (spinPulse.EditValue != null)
				{
					sdo.Dhst.PULSE = Parse.ToInt64(spinPulse.Value.ToString());
				}
				if (spinTemperature.EditValue != null)
				{
					sdo.Dhst.TEMPERATURE = Inventec.Common.Number.Get.RoundCurrency(spinTemperature.Value, 2);
				}
				if (spinWeight.EditValue != null)
				{
					sdo.Dhst.WEIGHT = Inventec.Common.Number.Get.RoundCurrency(spinWeight.Value, 2);
				}
				if (spinSPO2.EditValue != null)
				{
					sdo.Dhst.SPO2 = Inventec.Common.Number.Get.RoundCurrency(spinSPO2.Value, 2) / 100m;
				}
				HisServiceReqFilter _reqFilter = new HisServiceReqFilter();
				_reqFilter.TREATMENT_ID = treatmentId;
				_reqFilter.INTRUCTION_DATE__EQUAL = long.Parse(Inventec.Common.DateTime.Convert.SystemDateTimeToTimeNumber(DateTime.Now).ToString().Substring(0, 8) + "000000");
				_reqFilter.REQUEST_LOGINNAME__EXACT = ClientTokenManagerStore.ClientTokenManager.GetLoginName();
				_reqFilter.HAS_EXECUTE = true;
				List<HIS_SERVICE_REQ> dataReqs = new BackendAdapter(param).Get<List<HIS_SERVICE_REQ>>("api/HisServiceReq/Get", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, _reqFilter, param);
				dataReqs = dataReqs.Where((HIS_SERVICE_REQ o) => !o.TRACKING_ID.HasValue).ToList();
				if (dataReqs != null && dataReqs.Count > 0)
				{
					sdo.ServiceReqs = new List<TrackingServiceReq>();
					foreach (HIS_SERVICE_REQ item in dataReqs)
					{
						TrackingServiceReq ado = new TrackingServiceReq();
						ado.ServiceReqId = item.ID;
						ado.IsNotShowMedicine = false;
						ado.IsNotShowMaterial = false;
						ado.IsNotShowOutMedi = false;
						ado.IsNotShowOutMate = false;
						sdo.ServiceReqs.Add(ado);
					}
				}
				bool success = false;
				LogSystem.Debug(LogUtil.TraceData(LogUtil.GetMemberName(() => sdo), sdo));
				HIS_TRACKING resultData = new BackendAdapter(param).Post<HIS_TRACKING>("api/HisTracking/Create", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, sdo, param);
				if (resultData != null)
				{
					success = true;
				}
				WaitingManager.Hide();
				MessageManager.Show(param, success);
				SessionManager.ProcessTokenLost(param);
			}
		}
		catch (Exception ex)
		{
			WaitingManager.Hide();
			LogSystem.Warn(ex);
		}
	}

