			bool flag3 = (chkPART_EXAM_EYE_BLIND_COLOR__MMV.Checked = examServiceReqUpdateSDO.PartExamEyeBlindColor == 9);
			@checked = (checkEdit3.Checked = flag3);
			checkEdit2.Checked = @checked;
			goto IL_03e2;
			IL_038f:
			CheckEdit checkEdit4 = chkPART_EXAM_EYE_BLIND_COLOR__MMD;
			CheckEdit checkEdit5 = chkPART_EXAM_EYE_BLIND_COLOR__MMXLC;
			CheckEdit checkEdit6 = chkPART_EXAM_EYE_BLIND_COLOR__MMV;
			CheckEdit checkEdit7 = chkPART_EXAM_EYE_BLIND_COLOR__BT;
			bool flag6 = (chkPART_EXAM_EYE_BLIND_COLOR__MMTB.Checked = false);
			bool flag8 = (checkEdit7.Checked = flag6);
			flag3 = (checkEdit6.Checked = flag8);
			@checked = (checkEdit5.Checked = flag3);
			checkEdit4.Checked = @checked;
			goto IL_03e2;
			IL_03e2:
			txtMat.Text = examServiceReqUpdateSDO.PartExamEye;
			txtPART_EXAM_UPPER_JAW.Text = examServiceReqUpdateSDO.PartExamUpperJaw;
			txtPART_EXAM_LOWER_JAW.Text = examServiceReqUpdateSDO.PartExamLowerJaw;
