	private void BtnRefreshForFormOther()
	{
		try
		{
			LogSystem.Debug("BtnRefreshForFormOther");
			drBtnOther.DropDownControl = null;
			InitDrButtonOther();
		}
		catch (Exception ex)
		{
			LogSystem.Error(ex);
		}
	}

	private async Task InitDrButtonOther()
	{
		try
		{
			DXPopupMenu menu = new DXPopupMenu();
			DXMenuItem itemPhieuVoBenhAn = new DXMenuItem(Inventec.Common.Resource.Get.Value("IVT_LANGUAGE_KEY_PHIEU_VO_BENH_AN", ResourceLangManager.LanguageUCExamServiceReqExecute, LanguageManager.GetCulture()), onClickPhieuVoBenhAn);
			menu.Items.Add(itemPhieuVoBenhAn);
			DXMenuItem itemTrackingList = new DXMenuItem("Danh sách tờ điều trị", onClickTrackingList);
			menu.Items.Add(itemTrackingList);
			DXMenuItem itemTrackingCreate = new DXMenuItem(Inventec.Common.Resource.Get.Value("ExamServiceReqExecuteControl.btnTrackingCreateV2.Text", ResourceLangManager.LanguageUCExamServiceReqExecute, LanguageManager.GetCulture()), onClickTrackingCreate);
			menu.Items.Add(itemTrackingCreate);
			DXMenuItem itemAssBlood = new DXMenuItem(Inventec.Common.Resource.Get.Value("ExamServiceReqExecuteControl.btnAssBlood.Text", ResourceLangManager.LanguageUCExamServiceReqExecute, LanguageManager.GetCulture()), onClickAssBlood);
			menu.Items.Add(itemAssBlood);
			DXMenuItem itemnAccidentHurt = new DXMenuItem(Inventec.Common.Resource.Get.Value("ExamServiceReqExecuteControl.btnAccidentHurt.Text", ResourceLangManager.LanguageUCExamServiceReqExecute, LanguageManager.GetCulture()), onClickAccidenHurt);
			menu.Items.Add(itemnAccidentHurt);
			DXMenuItem itemnDebateDiagnostic = new DXMenuItem(Inventec.Common.Resource.Get.Value("ExamServiceReqExecuteControl.btnitemnDebateDiagnostic.Text", ResourceLangManager.LanguageUCExamServiceReqExecute, LanguageManager.GetCulture()), onClickDebateDiagnostic);
			menu.Items.Add(itemnDebateDiagnostic);
			DXMenuItem itemMedicalAssessment = new DXMenuItem("Giám định y khoa", onClickMedicalAssessment);
			menu.Items.Add(itemMedicalAssessment);
			DXMenuItem itemnDebateDiagnosticList = new DXMenuItem(Inventec.Common.Resource.Get.Value("ExamServiceReqExecuteControl.btnitemnDebateDiagnosticList.Text", ResourceLangManager.LanguageUCExamServiceReqExecute, LanguageManager.GetCulture()), onClickDebateDiagnosticList);
			menu.Items.Add(itemnDebateDiagnosticList);
			DXMenuItem itemnDrugReaction = new DXMenuItem("Phản ứng thuốc", onClickDrugReaction);
			menu.Items.Add(itemnDrugReaction);
			DXMenuItem itemnAssignPaan = new DXMenuItem(Inventec.Common.Resource.Get.Value("ExamServiceReqExecuteControl.btnAssignPaan.Text", ResourceLangManager.LanguageUCExamServiceReqExecute, LanguageManager.GetCulture()), onClickAssignPaan);
			menu.Items.Add(itemnAssignPaan);
			DXMenuItem itemTruyenDich = new DXMenuItem("Truyền dịch", onClickTruyenDich);
			menu.Items.Add(itemTruyenDich);
			DXMenuItem itemInCongKhaiDichVu = new DXMenuItem(Inventec.Common.Resource.Get.Value("ExamServiceReqExecuteControl.btnInCongKhaiDichVu", ResourceLangManager.LanguageUCExamServiceReqExecute, LanguageManager.GetCulture()), OnClickInCongKhaiDichVu);
			menu.Items.Add(itemInCongKhaiDichVu);
			DXMenuItem itemYcTamUng = new DXMenuItem(Inventec.Common.Resource.Get.Value("ExamServiceReqExecuteControl.btnRequestAdvance.Text", ResourceLangManager.LanguageUCExamServiceReqExecute, LanguageManager.GetCulture()), OnclickOpenMuduleRequestForAdvance);
			menu.Items.Add(itemYcTamUng);
			DXMenuItem itemXemGiayChuyenTuyen = new DXMenuItem("Giấy tờ đính kèm", OnClickOpenXemGiayChuyenTuyen);
			menu.Items.Add(itemXemGiayChuyenTuyen);
			FormOtherTreatmentProcessor form = new FormOtherTreatmentProcessor(treatment, BtnRefreshJsonUpdate);
			DXSubMenuItem subBenhAn = null;
			List<DXMenuItem> LstBar = form.GetDXMenuItem();
			if (LstBar != null && LstBar.Count > 0)
			{
				subBenhAn = new DXSubMenuItem(Inventec.Common.Resource.Get.Value("IVT_LANGUAGE_KEY_EXAM_SERVICE_REQ_EXCUTE_CONTROL_BENH_AN", ResourceLangManager.LanguageUCExamServiceReqExecute, LanguageManager.GetCulture()));
				DXMenuItem itemBenhAnNgoaiTruDayMat = new DXMenuItem(Inventec.Common.Resource.Get.Value("IVT_LANGUAGE_KEY_EXAM_SERVICE_REQ_EXCUTE_CONTROL_BENH_AN_NGOAI_TRU_DAY_MAT", ResourceLangManager.LanguageUCExamServiceReqExecute, LanguageManager.GetCulture()), BenhAnNgoaiTruDayMatClick);
				subBenhAn.Items.Add(itemBenhAnNgoaiTruDayMat);
				DXMenuItem itemBenhAnNgoaiTruGlaucoma = new DXMenuItem(Inventec.Common.Resource.Get.Value("IVT_LANGUAGE_KEY_EXAM_SERVICE_REQ_EXCUTE_CONTROL_BENH_AN_NGOAI_TRU_GLAUCOMA", ResourceLangManager.LanguageUCExamServiceReqExecute, LanguageManager.GetCulture()), BenhAnNgoaiTruGlaucomaClick);
				subBenhAn.Items.Add(itemBenhAnNgoaiTruGlaucoma);
			}
			menu.Items.Add(subBenhAn);
			HIS_ROOM _hisRoom = BackendDataWorker.Get<HIS_ROOM>().FirstOrDefault((HIS_ROOM p) => p.ID == moduleData.RoomId);
			if (HisConfigCFG.executeRoomPaymentOption == "2" && _hisRoom.DEFAULT_CASHIER_ROOM_ID.HasValue && _hisRoom.BILL_ACCOUNT_BOOK_ID.HasValue)
			{
				DXSubMenuItem subPay = new DXSubMenuItem("Thanh toán");
				if (treatment.IS_PAUSE == 1)
				{
					DXMenuItem itemThanhToanChiPhiVienPhi = new DXMenuItem("Thanh toán chi phí viện phí", ThanhToanChiPhiVienPhiClick);
					subPay.Items.Add(itemThanhToanChiPhiVienPhi);
				}
				DXMenuItem itemCauHinhKetNoiDauDocThe = new DXMenuItem("Cấu hình kết nối đầu đọc thẻ", CauHinhKetNoiDauDocTheClick);
				subPay.Items.Add(itemCauHinhKetNoiDauDocThe);
				menu.Items.Add(subPay);
			}
			DXSubMenuItem itemOtherForm = null;
			List<DXMenuItem> lstBar = form.GetDXMenuItem(new List<string> { "Frd000010" });
			if (lstBar != null && lstBar.Count > 0)
			{
				itemOtherForm = new DXSubMenuItem(Inventec.Common.Resource.Get.Value("IVT_LANGUAGE_KEY_EXAM_SERVICE_REQ_EXCUTE_CONTROL_FROM_KHAC", ResourceLangManager.LanguageUCExamServiceReqExecute, LanguageManager.GetCulture()));
				foreach (DXMenuItem item2 in lstBar)
				{
					itemOtherForm.Items.Add(item2);
				}
			}
			if (HisServiceReqResult != null && HisServiceReqResult.ServiceReq != null)
			{
				serviceReq = HisServiceReqResult.ServiceReq;
			}
			else
			{
				serviceReq = GetServiceReq();
			}
			FormOtherProcessor form2 = new FormOtherProcessor(serviceReq, BtnRefreshForFormOther, BtnRefreshForFormOther);
			List<DXMenuItem> lstBar2 = form2.GetDXMenuItem();
			if (lstBar2 != null && lstBar2.Count > 0)
			{
				if (itemOtherForm == null)
				{
					itemOtherForm = new DXSubMenuItem(Inventec.Common.Resource.Get.Value("IVT_LANGUAGE_KEY_EXAM_SERVICE_REQ_EXCUTE_CONTROL_FROM_KHAC", ResourceLangManager.LanguageUCExamServiceReqExecute, LanguageManager.GetCulture()));
				}
				foreach (DXMenuItem item in lstBar2)
				{
					itemOtherForm.Items.Add(item);
				}
			}
			if (itemOtherForm != null)
			{
				menu.Items.Add(itemOtherForm);
			}
			drBtnOther.DropDownControl = menu;
		}
		catch (Exception ex2)
		{
			Exception ex = ex2;
			LogSystem.Warn(ex);
		}
	}

	private void BtnRefreshJsonUpdate(object data)
	{
		try
		{
			if (data != null && data is HIS_TREATMENT)
			{
				treatment = (HIS_TREATMENT)data;
				if (treatment != null)
				{
					UpdateNeedSickLeaveCertControl(treatment.NEED_SICK_LEAVE_CERT);
				}
				InitDrButtonOther();
			}
		}
		catch (Exception ex)
		{
			LogSystem.Error(ex);
		}
	}

	private void UpdateNeedSickLeaveCertControl(short? needSickLeaveCert)
	{
		try
		{
			if (needSickLeaveCert.HasValue && needSickLeaveCert.Value == 1)
			{
				lblNeedSickLeaveCert.Text = HIS.Desktop.Plugins.ExamServiceReqExecute.Resources.ResourceMessage.BenhNhanCoYeuCauCapGiayNghiOm;
				lciNeedSickLeaveCert.Visibility = LayoutVisibility.Always;
			}
			else
			{
				lblNeedSickLeaveCert.Text = "";
				lciNeedSickLeaveCert.Visibility = LayoutVisibility.Never;
			}
		}
		catch (Exception ex)
		{
			LogSystem.Error(ex);
		}
	}

	private void ReloadMenu(object data)
	{
		if (data != null && data is DXMenuItem)
		{
			DXPopupMenu menu = btnPrint_ExamService.DropDownControl as DXPopupMenu;
			if (menu == null)
			{
				menu = new DXPopupMenu();
			}
			menu.Items.Add(data as DXMenuItem);
