				{
					printTreatmentEndTypeExtProcessor.Print(PrintTreatmentEndTypeExPrintType.TYPE.NGHI_OM, PrintTreatmentEndTypeExtProcessor.OPTION.PRINT__INIT_MENU);
				}
				else
				{
					printTreatmentEndTypeExtProcessor.Print(PrintTreatmentEndTypeExPrintType.TYPE.NGHI_OM, PrintTreatmentEndTypeExtProcessor.OPTION.INIT_MENU);
				}
				break;
			case PrintType.IN_GIAY_NGHI_DUONG_THAI:
				if (isPrint)
				{
					printTreatmentEndTypeExtProcessor.Print(PrintTreatmentEndTypeExPrintType.TYPE.NGHI_DUONG_THAI, PrintTreatmentEndTypeExtProcessor.OPTION.PRINT__INIT_MENU);
				}
				else
				{
					printTreatmentEndTypeExtProcessor.Print(PrintTreatmentEndTypeExPrintType.TYPE.NGHI_DUONG_THAI, PrintTreatmentEndTypeExtProcessor.OPTION.INIT_MENU);
				}
				break;
			case PrintType.IN_PHIEU_HEN_MO:
				if (isPrint)
				{
					printTreatmentEndTypeExtProcessor.Print(PrintTreatmentEndTypeExPrintType.TYPE.HEN_MO, PrintTreatmentEndTypeExtProcessor.OPTION.PRINT__INIT_MENU);
				}
				else
				{
					printTreatmentEndTypeExtProcessor.Print(PrintTreatmentEndTypeExPrintType.TYPE.HEN_MO, PrintTreatmentEndTypeExtProcessor.OPTION.INIT_MENU);
				}
				break;
