			{
				HisExpMestBloodViewFilter expMestBloodFilter = new HisExpMestBloodViewFilter();
				expMestBloodFilter.EXP_MEST_IDs = expMestList.Select((HIS_EXP_MEST o) => o.ID).ToList();
