	private void CheckBordereauType(ref bool isPhoiBHYT, ref bool isPhoiVienPhi)
	{
		try
		{
			if (SereServ8s == null || SereServ8s.Count <= 0)
			{
				return;
			}
			long patientTypeIdBHYT = HisPatientTypeCFG.PATIENT_TYPE_ID__BHYT;
			List<HIS_SERE_SERV> sereServ_BHYT = SereServ8s.Where((HIS_SERE_SERV o) => o.PATIENT_TYPE_ID == patientTypeIdBHYT).ToList();
			if (sereServ_BHYT != null && sereServ_BHYT.Count > 0)
			{
				isPhoiBHYT = true;
			}
			List<HIS_SERE_SERV> sereServ_VienPhi = SereServ8s.Where(delegate(HIS_SERE_SERV o)
			{
				decimal? num;
				int result;
				if (o.PATIENT_TYPE_ID == patientTypeIdBHYT)
				{
					if (o.PATIENT_TYPE_ID == patientTypeIdBHYT)
					{
						if (o.HEIN_LIMIT_PRICE.HasValue)
						{
							decimal? hEIN_LIMIT_PRICE = o.HEIN_LIMIT_PRICE;
							if (hEIN_LIMIT_PRICE.GetValueOrDefault() > default(decimal) && hEIN_LIMIT_PRICE.HasValue)
							{
								num = o.HEIN_LIMIT_PRICE * (decimal?)o.AMOUNT;
								goto IL_0107;
							}
						}
						num = o.VIR_PRICE_NO_ADD_PRICE * (decimal?)o.AMOUNT - o.VIR_TOTAL_HEIN_PRICE;
						goto IL_0107;
					}
					result = 0;
				}
				else
				{
					result = 1;
				}
				goto IL_012f;
				IL_012f:
				return (byte)result != 0;
				IL_0107:
				decimal? num2 = num;
				result = ((num2.GetValueOrDefault() > default(decimal) && num2.HasValue) ? 1 : 0);
				goto IL_012f;
			}).ToList();
			if (sereServ_VienPhi != null && sereServ_VienPhi.Count > 0)
			{
				isPhoiVienPhi = true;
			}
		}
		catch (Exception ex)
		{
			LogSystem.Warn(ex);
		}
	}

	private Dictionary<string, List<HIS_SERE_SERV>> GroupSereServByPatyAlterBhyt(List<HIS_SERE_SERV> listSereServ)
	{
		Dictionary<string, List<HIS_SERE_SERV>> dicSereServ = new Dictionary<string, List<HIS_SERE_SERV>>();
		try
		{
			foreach (HIS_SERE_SERV s in listSereServ)
			{
				if (s.PATIENT_TYPE_ID != HisPatientTypeCFG.PATIENT_TYPE_ID__BHYT || s.JSON_PATIENT_TYPE_ALTER == null)
				{
					continue;
				}
				HIS_PATIENT_TYPE_ALTER patyAlter = JsonConvert.DeserializeObject<HIS_PATIENT_TYPE_ALTER>(s.JSON_PATIENT_TYPE_ALTER);
				if (patyAlter != null)
				{
					string key = ToString(patyAlter);
					List<HIS_SERE_SERV> list;
					if (dicSereServ.ContainsKey(key))
					{
						list = dicSereServ[key];
					}
					else
					{
						list = new List<HIS_SERE_SERV>();
						dicSereServ.Add(key, list);
					}
					list.Add(s);
				}
			}
		}
		catch (Exception ex)
		{
			dicSereServ = null;
			LogSystem.Warn(ex);
		}
		return dicSereServ;
	}

	private string ToString(HIS_PATIENT_TYPE_ALTER patyAlter)
	{
		if (patyAlter != null)
		{
			return NVL(patyAlter.HEIN_CARD_NUMBER) + "|" + NVL(patyAlter.HEIN_MEDI_ORG_CODE) + "|" + NVL(patyAlter.LEVEL_CODE) + "|" + NVL(patyAlter.RIGHT_ROUTE_CODE) + "|" + NVL(patyAlter.RIGHT_ROUTE_TYPE_CODE) + "|" + NVL(patyAlter.JOIN_5_YEAR) + "|" + NVL(patyAlter.PAID_6_MONTH) + "|" + NVL(patyAlter.LIVE_AREA_CODE) + "|" + NVL(patyAlter.HNCODE);
		}
		return null;
	}

	private string NVL(string s)
	{
		return (!string.IsNullOrWhiteSpace(s)) ? s : "";
	}

	public string GetDefaultHeinRatioForView(string heinCardNumber, string treatmentTypeCode, string levelCode, string rightRouteCode)
	{
		string result = "";
		try
		{
			result = (new BhytHeinProcessor().GetDefaultHeinRatio(treatmentTypeCode, heinCardNumber, levelCode, rightRouteCode) ?? 0m) * 100m + "%";
		}
		catch (Exception ex)
		{
			LogSystem.Warn(ex);
		}
		return result;
	}

