	private void LoadSdaConfig()
	{
		try
		{
			requiredControl = Parse.ToInt64(HisConfigs.Get<string>("HIS.Desktop.Plugins.ExamServiceReqExecute.ControlRequired"));
			checkSameHeinCFG = Parse.ToInt64(HisConfigs.Get<string>("HIS.DESKTOP.TREATMENT_FINISH.CHECK_SAME_HEIN"));
