	private void LoadUCToPanelExecuteExt(UserControl uc, CheckEdit checkEdit)
	{
		try
		{
			panelExecuteExt.Controls.Clear();
			if (uc != null && checkEdit != null)
			{
				lciNotice.Visibility = (checkEdit.Checked ? LayoutVisibility.Never : LayoutVisibility.Always);
				lciIconNotice.Visibility = (checkEdit.Checked ? LayoutVisibility.Never : LayoutVisibility.Always);
				uc.Dock = DockStyle.Fill;
				panelExecuteExt.Controls.Add(uc);
			}
			else if (uc == null && checkEdit != null && !checkEdit.Checked)
			{
				lciNotice.Visibility = LayoutVisibility.Always;
				lciIconNotice.Visibility = LayoutVisibility.Always;
			}
			else
			{
				lciNotice.Visibility = LayoutVisibility.Never;
				lciIconNotice.Visibility = LayoutVisibility.Never;
			}
			CreateThreadProcessHideControl();
		}
		catch (Exception ex)
		{
			LogSystem.Warn(ex);
		}
	}

