	private bool DelegateRunPrinter(string printTypeCode, string fileName)
	{
		bool result = false;
		try
		{
			switch (printTypeCode)
			{
			case "Mps000174":
				LoadBieuMauPhieuYCBenhAnNgoaiTru(printTypeCode, fileName, ref result);
				break;
			case "Mps000007":
				LoadBieuMauPhieuYCKhamBenhVaoVien(printTypeCode, fileName, ref result);
				break;
			case "Mps000374":
				LoadBieuMauPhieuYCKhamBenhCapCuu(printTypeCode, fileName, ref result);
				break;
			case "Mps000362":
				LoadBieuMauPhieuBenhAnNgoaiChan(printTypeCode, fileName, ref result);
				break;
			case "Mps000010":
				LoadBieuMauGiayHenKham(printTypeCode, fileName, ref result);
				break;
			case "Mps000008":
				LoadBieuMauGiayRaVien(printTypeCode, fileName, ref result);
				break;
			case "Mps000011":
				LoadBieuMauGiayChuyenVien(printTypeCode, fileName, ref result);
				break;
			case "Mps000268":
				LoadBieuMauGiayBaoTu(printTypeCode, fileName, ref result);
				break;
			case "Mps000269":
				LoadBieuMauGiayNghiOm(printTypeCode, fileName, ref result);
				break;
			case "Mps000389":
				LoadBieuMauGiayHenMo(printTypeCode, fileName, ref result);
				break;
			case "Mps000401":
				LoadBieuMauGiayDongYXetNghiemHIV(printTypeCode, fileName, ref result);
				break;
			case "Mps000436":
				LoadBieuMauGiayXetNghiemViKhuanLao(printTypeCode, fileName, ref result);
				break;
			case "Mps000437":
				ExamServiceReqExcuteControl__Print__Sars_nCOV_2(printTypeCode, fileName, ref result);
				break;
			case "Mps000438":
				LoadBieuMauGiayXetNghiemDom(printTypeCode, fileName, ref result);
				break;
			case "Mps000315":
				LoadPhieuKiemTraKhamSucKhoeDinhKy(printTypeCode, fileName, ref result);
				break;
			case "Mps000478":
				ProcessPrintMps000478(printTypeCode, fileName, ref result);
				break;
			case "Mps000111":
				ProcessPrintMps000111(printTypeCode, fileName, ref result);
				break;
			case "Mps000485":
				ProcessPrintMps000485(printTypeCode, fileName, ref result);
				break;
			case "Mps000178":
				ProcessPrintMps000178(printTypeCode, fileName, ref result);
				break;
			}
		}
		catch (Exception ex)
		{
			LogSystem.Error(ex);
		}
		return result;
	}

	private void ProcessPrintMps000111(string printTypeCode, string fileName, ref bool result)
	{
		try
		{
			string printerName = "";
			if (GlobalVariables.dicPrinter.ContainsKey(printTypeCode))
			{
				printerName = GlobalVariables.dicPrinter[printTypeCode];
			}
			if (resultEPayment != null)
			{
				HisSereServFilter ssFilter = new HisSereServFilter();
				ssFilter.IDs = resultEPayment.SereServs.Select((V_HIS_SERE_SERV o) => o.ID).ToList();
				List<HIS_SERE_SERV> hisSereServs = new BackendAdapter(new CommonParam()).Get<List<HIS_SERE_SERV>>("api/HisSereServ/Get", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, ssFilter, null);
				V_HIS_PATIENT_TYPE_ALTER patientAlter = new V_HIS_PATIENT_TYPE_ALTER();
				if (patient != null)
				{
					HisPatientTypeAlterViewFilter ft = new HisPatientTypeAlterViewFilter();
					ft.TDL_PATIENT_ID = patient.ID;
					patientAlter = new BackendAdapter(new CommonParam()).Get<List<V_HIS_PATIENT_TYPE_ALTER>>("api/HisPatientTypeAlter/GetView", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, ft, null).FirstOrDefault();
				}
				HisDepartmentTranLastFilter departLastFilter = new HisDepartmentTranLastFilter();
				departLastFilter.TREATMENT_ID = resultEPayment.Transaction.TREATMENT_ID.Value;
				departLastFilter.BEFORE_LOG_TIME = System.Convert.ToInt64(DateTime.Now.ToString("yyyyMMddHHmmss"));
				V_HIS_DEPARTMENT_TRAN departmentTran = new BackendAdapter(new CommonParam()).Get<V_HIS_DEPARTMENT_TRAN>("api/HisDepartmentTran/GetLastByTreatmentId", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, departLastFilter, null);
				Mps000111PDO pdo = new Mps000111PDO(resultEPayment.Transaction, patient, null, hisSereServs, departmentTran, patientAlter, treatment.TDL_PATIENT_TYPE_ID.Value);
				result = MpsPrinter.Run(new PrintData(printTypeCode, fileName, pdo, MPS.ProcessorBase.PrintConfig.PreviewType.PrintNow, printerName));
			}
		}
		catch (Exception ex)
		{
			WaitingManager.Hide();
			LogSystem.Error(ex);
		}
	}

	private void PrintProcess(PrintType printType)
	{
		try
		{
			switch (printType)
			{
			case PrintType.KHAM_BENH_VAO_VIEN:
				richEditorMain.RunPrintTemplate("Mps000007", DelegateRunPrinter);
				break;
			case PrintType.BENH_AN_CAP_CUU_MPS374:
				richEditorMain.RunPrintTemplate("Mps000374", DelegateRunPrinter);
				break;
			case PrintType.BENH_AN_NGOAI_TRU:
				richEditorMain.RunPrintTemplate("Mps000174", DelegateRunPrinter);
				break;
			case PrintType.IN_BENH_AN_NGOAI_CHAN:
				richEditorMain.RunPrintTemplate("Mps000362", DelegateRunPrinter);
				break;
			case PrintType.BIEU_MAU_KHAC_PHIEU_PTTT:
				LoadBieuMauKhacPhieuPTTT();
				break;
			case PrintType.PHIEU_TU_VAN:
				LoadBieuMauKhacPhieuTuVan();
				break;
